{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Rilzabrutinib, the closest analogue sharing the same pyrazolopyrimidine core and 4-phenoxyphenyl substituent, had an absolute oral bioavailability of only 6.4% in healthy subjects, strongly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, a related BTK inhibitor with the same core but a different substituent, had an absolute F of 25.3% in healthy subjects, providing contradictory evidence that this core can achieve F ≥20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "Zongertinib, an acrylamide-containing covalent inhibitor with a phenoxy substituent, was predicted to have 41% human oral bioavailability, but this is a preclinical prediction with low structural transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low. The highest-transfer experimental anchor (rilzabrutinib) shows absolute F of only ~5-6% in humans and shares the query's core and phenoxyphenyl group; less similar moderate/high-F analogues do not override this direct evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "The closest analogue differs in the acrylamide warhead substituent, which could alter first-pass metabolism and absorption.",
    "Formulation and dose effects on F are not fully matched between the evidence and the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

